# ruff: file-ignore[hardcoded-sql-expression]  # schema names are generated by the tests
"""Tests for the migrations runner.

The database tests run only when the ``SHARED_TEST_POSTGRES`` environment variable holds a connection string.
Each test works in its own throwaway schema, which is dropped afterwards.
"""

import os
import secrets
from typing import TYPE_CHECKING, Any

import asyncpg
import pytest

from shared.concepts.migrations import Migration, MigrationError, apply, load

if TYPE_CHECKING:
    from collections.abc import AsyncIterator
    from pathlib import Path

DSN = os.environ.get("SHARED_TEST_POSTGRES")
needs_postgres = pytest.mark.skipif(DSN is None, reason="SHARED_TEST_POSTGRES is not set")


def write(directory: Path, files: dict[str, str]) -> Path:
    directory.mkdir(exist_ok=True)
    for name, sql in files.items():
        (directory / name).write_text(sql, encoding="utf-8", newline="")
    return directory


# --- Reading the files ------------------------------------------------------------------------------------------------


def test_load_sorts_by_version_and_ignores_other_files(tmp_path: Path) -> None:
    write(tmp_path, {"0002_second.sql": "SELECT 2;", "0001_baseline.sql": "SELECT 1;", "README.md": "# notes"})
    assert [(m.version, m.name) for m in load(tmp_path)] == [(1, "baseline"), (2, "second")]


@pytest.mark.parametrize("name", ["1_short.sql", "0001-dash.sql", "0001_Upper.sql", "baseline.sql"])
def test_load_rejects_wrongly_named_files(tmp_path: Path, name: str) -> None:
    write(tmp_path, {name: "SELECT 1;"})
    with pytest.raises(MigrationError, match="isn't named like"):
        load(tmp_path)


def test_load_rejects_duplicate_versions(tmp_path: Path) -> None:
    write(tmp_path, {"0001_baseline.sql": "SELECT 1;", "0001_other.sql": "SELECT 1;"})
    with pytest.raises(MigrationError, match="share version 1"):
        load(tmp_path)


def test_load_rejects_missing_folder(tmp_path: Path) -> None:
    with pytest.raises(MigrationError, match="doesn't exist"):
        load(tmp_path / "missing")


def test_checksum_ignores_line_endings() -> None:
    assert (
        Migration(1, "baseline", "SELECT 1;\r\nSELECT 2;\r\n").checksum
        == Migration(1, "baseline", "SELECT 1;\nSELECT 2;\n").checksum
    )


# --- Applying them ----------------------------------------------------------------------------------------------------


@pytest.fixture
async def schema_pool() -> AsyncIterator[tuple[str, asyncpg.Pool[Any]]]:
    """Yield a fresh schema name and a pool with it as the ``search_path``. The schema itself isn't created."""
    assert DSN is not None
    schema = f"migrations_test_{secrets.token_hex(4)}"
    pool = await asyncpg.create_pool(DSN, min_size=1, max_size=2, server_settings={"search_path": schema})
    try:
        yield schema, pool
    finally:
        await pool.execute(f"DROP SCHEMA IF EXISTS {schema} CASCADE")
        await pool.close()


def migrations_for(tmp_path: Path, schema: str, *extra: tuple[str, str]) -> Path:
    files = {
        "0001_baseline.sql": f"CREATE TABLE {schema}.things (id INTEGER PRIMARY KEY);",
        "0002_add_name.sql": f"ALTER TABLE {schema}.things ADD COLUMN name TEXT;",
    }
    files.update(extra)
    return write(tmp_path / "migrations", files)


async def recorded(pool: asyncpg.Pool[Any], schema: str) -> list[int]:
    return [row["version"] for row in await pool.fetch(f"SELECT version FROM {schema}.schema_migrations ORDER BY 1")]


async def columns(pool: asyncpg.Pool[Any], schema: str, table: str) -> list[str]:
    query = """
        SELECT column_name FROM information_schema.columns
        WHERE table_schema = $1 AND table_name = $2
        ORDER BY ordinal_position
    """
    return [row["column_name"] for row in await pool.fetch(query, schema, table)]


@needs_postgres
async def test_applies_everything_to_an_empty_schema_once(
    tmp_path: Path, schema_pool: tuple[str, asyncpg.Pool[Any]]
) -> None:
    schema, pool = schema_pool
    directory = migrations_for(tmp_path, schema)

    applied = await apply(pool, directory, schema=schema)

    assert [m.version for m in applied] == [1, 2]
    assert await recorded(pool, schema) == [1, 2]
    assert await columns(pool, schema, "things") == ["id", "name"]
    assert await apply(pool, directory, schema=schema) == []


@needs_postgres
async def test_applies_only_new_files(tmp_path: Path, schema_pool: tuple[str, asyncpg.Pool[Any]]) -> None:
    schema, pool = schema_pool
    directory = migrations_for(tmp_path, schema)
    await apply(pool, directory, schema=schema)

    write(directory, {"0003_add_size.sql": f"ALTER TABLE {schema}.things ADD COLUMN size INTEGER;"})
    applied = await apply(pool, directory, schema=schema)

    assert [m.version for m in applied] == [3]
    assert await columns(pool, schema, "things") == ["id", "name", "size"]


@needs_postgres
async def test_records_the_baseline_of_an_existing_schema_without_running_it(
    tmp_path: Path, schema_pool: tuple[str, asyncpg.Pool[Any]], caplog: pytest.LogCaptureFixture
) -> None:
    schema, pool = schema_pool
    await pool.execute(f"CREATE SCHEMA {schema}; CREATE TABLE {schema}.things (id INTEGER PRIMARY KEY);")
    directory = migrations_for(tmp_path, schema)

    applied = await apply(pool, directory, schema=schema)  # running the baseline would fail: the table exists

    assert [m.version for m in applied] == [2]
    assert await recorded(pool, schema) == [1, 2]
    assert "recorded as applied without running it" in caplog.text


@needs_postgres
async def test_a_failing_migration_is_rolled_back_and_stops_the_later_ones(
    tmp_path: Path, schema_pool: tuple[str, asyncpg.Pool[Any]]
) -> None:
    schema, pool = schema_pool
    directory = migrations_for(
        tmp_path,
        schema,
        ("0003_broken.sql", f"CREATE TABLE {schema}.half_done (id INTEGER); SELECT * FROM {schema}.no_such_table;"),
        ("0004_after.sql", f"CREATE TABLE {schema}.after (id INTEGER);"),
    )

    with pytest.raises(asyncpg.UndefinedTableError):
        await apply(pool, directory, schema=schema)

    assert await recorded(pool, schema) == [1, 2]
    assert await pool.fetchval("SELECT to_regclass($1)", f"{schema}.half_done") is None
    assert await pool.fetchval("SELECT to_regclass($1)", f"{schema}.after") is None
    # the advisory lock was released: another run gets past it and fails on the same file again
    with pytest.raises(asyncpg.UndefinedTableError):
        await apply(pool, directory, schema=schema)


@needs_postgres
async def test_warns_about_changed_and_missing_files(
    tmp_path: Path, schema_pool: tuple[str, asyncpg.Pool[Any]], caplog: pytest.LogCaptureFixture
) -> None:
    schema, pool = schema_pool
    directory = migrations_for(tmp_path, schema)
    await apply(pool, directory, schema=schema)

    write(directory, {"0002_add_name.sql": f"ALTER TABLE {schema}.things ADD COLUMN name VARCHAR;"})
    (directory / "0001_baseline.sql").unlink()
    assert await apply(pool, directory, schema=schema) == []

    assert "0002_add_name.sql changed after it was applied" in caplog.text
    assert "has version 0001 applied, but there's no file for it" in caplog.text


async def test_rejects_unsafe_schema_names(tmp_path: Path) -> None:
    with pytest.raises(MigrationError, match="plain lowercase identifier"):
        await apply(None, tmp_path, schema="bad; DROP SCHEMA x")  # ty: ignore[invalid-argument-type]
